'use client';

import { useEffect, useMemo, useState } from 'react';
import { Loader2, Plus, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet';
import { CMV_STORE_LABELS } from '@/lib/nfe/ui-labels';

type Produto = { estoqueInsumoId: string; nome: string; unidade: string };
type ItemForm = {
  key: string;
  estoqueInsumoId: string;
  nome: string;
  unidade: string;
  quantidade: string;
  custoUnitario: string;
  custoOrigem: string | null;
};

export type TransferenciaFormPrefill = {
  tipoLado: 'SAIDA' | 'ENTRADA';
  lojaOrigem: string;
  lojaDestino: string;
  data: string;
  numero: string;
  observacao?: string | null;
  itens?: Array<{
    estoqueInsumoId: string;
    nome: string;
    unidade: string;
    quantidade: number;
    custoUnitario: number | null;
  }>;
};

export function TransferenciaForm({
  open,
  onOpenChange,
  produtos,
  lojasOpts,
  lojaPadrao,
  onSaved,
  prefill,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  produtos: Produto[];
  lojasOpts: string[];
  lojaPadrao: string;
  onSaved: () => Promise<void>;
  prefill?: TransferenciaFormPrefill | null;
}) {
  const [tipoLado, setTipoLado] = useState<'SAIDA' | 'ENTRADA'>('SAIDA');
  const [lojaA, setLojaA] = useState(lojaPadrao);
  const [lojaB, setLojaB] = useState('');
  const [data, setData] = useState(() => new Date().toISOString().slice(0, 10));
  const [numero, setNumero] = useState('');
  const [observacao, setObservacao] = useState('');
  const [itens, setItens] = useState<ItemForm[]>([]);
  const [busca, setBusca] = useState('');
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setMsg(null);
    setBusca('');
    if (prefill) {
      setTipoLado(prefill.tipoLado);
      setLojaA(prefill.tipoLado === 'SAIDA' ? prefill.lojaOrigem : prefill.lojaDestino);
      setLojaB(prefill.tipoLado === 'SAIDA' ? prefill.lojaDestino : prefill.lojaOrigem);
      setData(prefill.data);
      setNumero(prefill.numero);
      setObservacao(prefill.observacao || '');
      setItens(
        (prefill.itens || []).map((it) => ({
          key: `${it.estoqueInsumoId}-${prefill.tipoLado}`,
          estoqueInsumoId: it.estoqueInsumoId,
          nome: it.nome,
          unidade: it.unidade,
          quantidade: it.quantidade ? String(it.quantidade).replace('.', ',') : '',
          custoUnitario:
            it.custoUnitario != null
              ? String(it.custoUnitario).replace('.', ',')
              : '',
          custoOrigem: null,
        })),
      );
      return;
    }
    setTipoLado('SAIDA');
    setLojaA(lojaPadrao);
    setLojaB('');
    setNumero('');
    setObservacao('');
    setItens([]);
  }, [open, lojaPadrao, prefill]);

  const lojaOrigem = tipoLado === 'SAIDA' ? lojaA : lojaB;
  const lojaDestino = tipoLado === 'SAIDA' ? lojaB : lojaA;
  const outras = lojasOpts.filter((s) => s !== lojaA);

  const sugestoes = useMemo(() => {
    const q = busca.trim().toLowerCase();
    if (q.length < 1) return [];
    const ja = new Set(itens.map((i) => i.estoqueInsumoId));
    return produtos
      .filter((p) => !ja.has(p.estoqueInsumoId) && p.nome.toLowerCase().includes(q))
      .slice(0, 8);
  }, [busca, produtos, itens]);

  const addProduto = async (p: Produto) => {
    setBusca('');
    let custo = '';
    let origem: string | null = null;
    if (lojaOrigem) {
      const comp = data.slice(0, 7);
      const res = await fetch(
        `/api/cmv-real/transferencias?acao=custo&lojaOrigem=${lojaOrigem}&estoqueInsumoId=${p.estoqueInsumoId}&competencia=${comp}`,
      );
      const d = await res.json();
      if (res.ok && d.custo != null) {
        custo = String(d.custo).replace('.', ',');
        origem = d.origem;
      }
    }
    setItens((prev) => [
      ...prev,
      {
        key: `${p.estoqueInsumoId}-${Date.now()}`,
        estoqueInsumoId: p.estoqueInsumoId,
        nome: p.nome,
        unidade: p.unidade,
        quantidade: '',
        custoUnitario: custo,
        custoOrigem: origem,
      },
    ]);
  };

  const salvar = async () => {
    setSaving(true);
    setMsg(null);
    try {
      if (!lojaB) throw new Error('Escolha a outra loja');
      const payloadItens = itens.map((it) => ({
        estoqueInsumoId: it.estoqueInsumoId,
        quantidade: Number(it.quantidade.replace(',', '.')),
        custoUnitario: it.custoUnitario
          ? Number(it.custoUnitario.replace(',', '.'))
          : null,
      }));
      if (payloadItens.some((i) => !(i.quantidade > 0))) {
        throw new Error('Informe a quantidade de cada item');
      }
      const res = await fetch('/api/cmv-real/transferencias', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tipoLado,
          lojaOrigem,
          lojaDestino,
          data,
          numeroDocumento: numero,
          observacao: observacao || undefined,
          itens: payloadItens,
        }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || 'Falha');
      setItens([]);
      setNumero('');
      setObservacao('');
      onOpenChange(false);
      await onSaved();
    } catch (e) {
      setMsg(e instanceof Error ? e.message : 'Erro');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="!inset-0 !h-full !w-full !max-w-none overflow-y-auto bg-card border-border p-4 sm:!inset-y-0 sm:!right-0 sm:!left-auto sm:!h-full sm:!w-full sm:!max-w-md sm:p-6"
      >
        <SheetHeader className="text-left pr-8">
          <SheetTitle className="text-base font-semibold">
            {prefill ? 'Registrar outro lado' : 'Nova transferência'}
          </SheetTitle>
          <SheetDescription className="text-sm text-muted-foreground">
            {prefill
              ? 'Confira quantidades e confirme o lado que faltava.'
              : 'Lance na hora que a mercadoria sai ou chega.'}
          </SheetDescription>
        </SheetHeader>

        <div className="mt-6 space-y-6">
          <div className="grid grid-cols-2 gap-2">
            <Button
              type="button"
              size="lg"
              variant={tipoLado === 'SAIDA' ? 'default' : 'outline'}
              className="h-12 text-sm"
              disabled={Boolean(prefill)}
              onClick={() => setTipoLado('SAIDA')}
            >
              Saiu da loja
            </Button>
            <Button
              type="button"
              size="lg"
              variant={tipoLado === 'ENTRADA' ? 'default' : 'outline'}
              className="h-12 text-sm"
              disabled={Boolean(prefill)}
              onClick={() => setTipoLado('ENTRADA')}
            >
              Chegou na loja
            </Button>
          </div>

          <div className="space-y-2">
            <Label className="text-sm">Sua loja</Label>
            <select
              className="h-12 w-full rounded-md border border-input bg-background px-3 text-sm"
              value={lojaA}
              disabled={Boolean(prefill)}
              onChange={(e) => {
                setLojaA(e.target.value);
                if (e.target.value === lojaB) setLojaB('');
              }}
            >
              {lojasOpts.map((s) => (
                <option key={s} value={s}>
                  {CMV_STORE_LABELS[s] || s}
                </option>
              ))}
            </select>
          </div>

          <div className="space-y-2">
            <Label className="text-sm">
              {tipoLado === 'SAIDA' ? 'Destino' : 'Origem'}
            </Label>
            <select
              className="h-12 w-full rounded-md border border-input bg-background px-3 text-sm"
              value={lojaB}
              disabled={Boolean(prefill)}
              onChange={(e) => setLojaB(e.target.value)}
            >
              <option value="">Escolher loja…</option>
              {outras.map((s) => (
                <option key={s} value={s}>
                  {CMV_STORE_LABELS[s] || s}
                </option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-2">
              <Label className="text-sm">Data</Label>
              <Input
                type="date"
                value={data}
                disabled={Boolean(prefill)}
                onChange={(e) => setData(e.target.value)}
                className="h-12"
              />
            </div>
            <div className="space-y-2">
              <Label className="text-sm">Nº documento</Label>
              <Input
                value={numero}
                disabled={Boolean(prefill)}
                onChange={(e) => setNumero(e.target.value)}
                placeholder="Ex.: 12"
                className="h-12"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label className="text-sm">Adicionar produto</Label>
            <Input
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              placeholder="Buscar no catálogo…"
              className="h-12"
              autoComplete="off"
            />
            {sugestoes.length > 0 && (
              <ul className="rounded-md border border-border bg-popover divide-y divide-border">
                {sugestoes.map((p) => (
                  <li key={p.estoqueInsumoId}>
                    <button
                      type="button"
                      className="w-full text-left px-3 py-3 text-sm hover:bg-muted"
                      onClick={() => void addProduto(p)}
                    >
                      <span className="text-foreground">{p.nome}</span>
                      <span className="ml-2 text-xs text-muted-foreground">
                        {p.unidade}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <div className="space-y-3">
            {itens.map((it) => (
              <div
                key={it.key}
                className="rounded-md border border-border p-3 space-y-2"
              >
                <div className="flex items-start justify-between gap-2">
                  <p className="text-sm font-medium text-foreground">{it.nome}</p>
                  <button
                    type="button"
                    className="text-muted-foreground p-1"
                    onClick={() =>
                      setItens((prev) => prev.filter((x) => x.key !== it.key))
                    }
                    aria-label="Remover item"
                  >
                    <Trash2 className="size-4" />
                  </button>
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">
                      Qtd ({it.unidade})
                    </p>
                    <Input
                      inputMode="decimal"
                      value={it.quantidade}
                      onChange={(e) =>
                        setItens((prev) =>
                          prev.map((x) =>
                            x.key === it.key
                              ? { ...x, quantidade: e.target.value }
                              : x,
                          ),
                        )
                      }
                      className="h-12 tabular-nums"
                    />
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">
                      Custo / {it.unidade}
                    </p>
                    <Input
                      inputMode="decimal"
                      value={it.custoUnitario}
                      onChange={(e) =>
                        setItens((prev) =>
                          prev.map((x) =>
                            x.key === it.key
                              ? { ...x, custoUnitario: e.target.value, custoOrigem: 'CUSTO_MANUAL' }
                              : x,
                          ),
                        )
                      }
                      className="h-12 tabular-nums"
                    />
                  </div>
                </div>
                {it.custoOrigem && it.custoOrigem !== 'CUSTO_MANUAL' ? (
                  <p className="text-xs text-muted-foreground">Custo sugerido da origem</p>
                ) : it.custoOrigem === 'CUSTO_MANUAL' ? (
                  <p className="text-xs text-muted-foreground">Custo manual</p>
                ) : (
                  <p className="text-xs text-warning">Preencha o custo — sem histórico</p>
                )}
              </div>
            ))}
            {itens.length === 0 ? (
              <p className="text-sm text-muted-foreground">
                Nenhum item. Busque e toque para adicionar.
              </p>
            ) : null}
          </div>

          <Input
            value={observacao}
            onChange={(e) => setObservacao(e.target.value)}
            placeholder="Observação (opcional)"
            className="h-12"
          />

          {msg ? (
            <p className="text-sm text-warning" role="alert">
              {msg}
            </p>
          ) : null}

          <Button
            type="button"
            size="lg"
            className="w-full h-12"
            disabled={saving || itens.length === 0 || !numero.trim()}
            onClick={() => void salvar()}
          >
            {saving ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />}
            Registrar {tipoLado === 'SAIDA' ? 'saída' : 'entrada'}
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}
